import{_ as t,o as e,c as s,a2 as n}from"./chunks/framework.C4u7U0Dw.js";const _=JSON.parse('{"title":"第 8 章 AI 团队：一句话召唤多智能体协作","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第一篇 使用手册：先把我用起来/第 8 章 AI 团队：一句话召唤多智能体协作.md","filePath":"bluebook/第一篇 使用手册：先把我用起来/第 8 章 AI 团队：一句话召唤多智能体协作.md"}'),l={name:"bluebook/第一篇 使用手册：先把我用起来/第 8 章 AI 团队：一句话召唤多智能体协作.md"};function d(i,a,o,r,p,h){return e(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="第-8-章-ai-团队-一句话召唤多智能体协作" tabindex="-1">第 8 章 AI 团队：一句话召唤多智能体协作 <a class="header-anchor" href="#第-8-章-ai-团队-一句话召唤多智能体协作" aria-label="Permalink to &quot;第 8 章 AI 团队：一句话召唤多智能体协作&quot;">​</a></h1><h2 id="_8-1-一个人的算力不够时" tabindex="-1">8.1 一个人的算力不够时 <a class="header-anchor" href="#_8-1-一个人的算力不够时" aria-label="Permalink to &quot;8.1 一个人的算力不够时&quot;">​</a></h2><p>当任务足够复杂——既要做产品设计、又要写代码、又要写测试、还要写文档——单打独斗就不划算了。这时，我可以<strong>组建一支 AI 团队</strong>：多个智能体各司其职，并行推进，我作为 Leader 负责协调和把关。</p><h2 id="_8-2-什么时候值得开团队" tabindex="-1">8.2 什么时候值得开团队 <a class="header-anchor" href="#_8-2-什么时候值得开团队" aria-label="Permalink to &quot;8.2 什么时候值得开团队&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>单打独斗</th><th>开团队</th></tr></thead><tbody><tr><td>大项目全流程（开发+测试+文档）</td><td>串行，慢</td><td>并行，快</td></tr><tr><td>需要多角色视角</td><td>一个视角</td><td>多角色互查</td></tr><tr><td>任务可明确拆解</td><td>一个人做到底</td><td>分派给专人</td></tr><tr><td>高风险交付</td><td>凭感觉</td><td>有专职 reviewer</td></tr></tbody></table><p><strong>判断标准：任务能否清晰拆成几个相对独立的子任务？</strong> 能 → 值得；不能 → 先一个人干。</p><h2 id="_8-3-团队怎么组建" tabindex="-1">8.3 团队怎么组建 <a class="header-anchor" href="#_8-3-团队怎么组建" aria-label="Permalink to &quot;8.3 团队怎么组建&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你：&quot;帮我做个团队，把 X 项目从开发到测试到文档全包了&quot;</span></span>
<span class="line"><span>我（Leader）：</span></span>
<span class="line"><span>  1. 确认模型配置（有哪些可用模型/后端）</span></span>
<span class="line"><span>  2. 说明团队分工方案（角色表）</span></span>
<span class="line"><span>  3. 你确认后，创建团队</span></span>
<span class="line"><span>  4. 生成每个成员（如：开发、测试）</span></span>
<span class="line"><span>  5. 给每个成员下发初始任务</span></span></code></pre></div><p>一个典型团队配置：</p><table tabindex="0"><thead><tr><th>角色</th><th>职责</th></tr></thead><tbody><tr><td>Leader（我）</td><td>拆任务、派活、验收、协调</td></tr><tr><td>开发</td><td>实现功能</td></tr><tr><td>测试</td><td>写测试、跑测试、报告问题</td></tr></tbody></table><h2 id="_8-4-团队协作的工作流" tabindex="-1">8.4 团队协作的工作流 <a class="header-anchor" href="#_8-4-团队协作的工作流" aria-label="Permalink to &quot;8.4 团队协作的工作流&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Leader 拆解任务 → 分派给成员 → 成员执行并回报</span></span>
<span class="line"><span>→ Leader 汇总/互查 → 发现问题 → 打回修订 → 验收交付</span></span></code></pre></div><p>我作为 Leader 会用任务看板管理进度：谁在做什么、谁被谁阻塞、哪些已完成——一目了然。</p><h2 id="_8-5-团队协作的纪律" tabindex="-1">8.5 团队协作的纪律 <a class="header-anchor" href="#_8-5-团队协作的纪律" aria-label="Permalink to &quot;8.5 团队协作的纪律&quot;">​</a></h2><ul><li><strong>先出方案再建团</strong>：分工表先给你确认，不擅自开团；</li><li><strong>任务要拆得清</strong>：子任务之间边界明确，减少互相等待；</li><li><strong>Leader 要验收</strong>：不是派完活就结束，而是要检查结果；</li><li><strong>不合适就撤</strong>：任务缩小了，可以关掉多余成员，不让团队空转。</li></ul><h2 id="_8-6-单人-vs-团队决策表" tabindex="-1">8.6 单人 vs 团队决策表 <a class="header-anchor" href="#_8-6-单人-vs-团队决策表" aria-label="Permalink to &quot;8.6 单人 vs 团队决策表&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>小任务/探索性任务/需求未定   → 单人，先跑通</span></span>
<span class="line"><span>大项目/多角色/可拆解/交付高风险 → 团队，并行干</span></span>
<span class="line"><span>需求变了/任务缩小           → 收缩回单人</span></span></code></pre></div><h2 id="_8-7-练习" tabindex="-1">8.7 练习 <a class="header-anchor" href="#_8-7-练习" aria-label="Permalink to &quot;8.7 练习&quot;">​</a></h2><ol><li>想一个你手头的大任务，试着向我描述&quot;我想开个团队做这件事&quot;。</li><li>观察我给出的团队分工方案：角色是否合理？任务是否可拆？</li><li>确认后，走一遍&quot;建团 → 派活 → 汇报 → 验收&quot;全流程。</li></ol><blockquote><p>小结：AI 团队不是炫技，而是<strong>把复杂度拆成可并行、可验收的单元</strong>。第 16 章会讲更多协作细节，第 18 章教你设计自己的多 Agent 系统。</p></blockquote>`,20)])])}const b=t(l,[["render",d]]);export{_ as __pageData,b as default};
